# Livne test set for S={2,3,5}: quadratic characters of Q unramified outside S are generated by -1,2,3,5 (r=4);
# T = one good prime per nonzero Frobenius pattern in F_2^4. CONTROL: Legendre via Euler's criterion equals quadratic-reciprocity value for (-1/p),(2/p).
def leg(a, p): return 1 if pow(a % p, (p - 1) // 2, p) == 1 else -1
P = [p for p in range(7, 1501) if all(p % d for d in range(2, int(p**.5) + 1))]
ctl = all(leg(-1, p) == (1 if p % 4 == 1 else -1) and leg(2, p) == (1 if p % 8 in (1, 7) else -1) for p in P)
T = {}
for p in P:
    v = tuple(0 if leg(a, p) == 1 else 1 for a in (-1, 2, 3, 5))
    if v not in T: T[v] = p   # E91: include the identity class (Livne Prop 4.11 non-cubic set), not only nonzero patterns
print('CONTROL:', 'PASS' if ctl else 'FAIL', '| classes covered', len(T), 'of 16 | max prime in T', max(T.values()), '| T =', sorted(T.values()))
